#!/usr/bin/env python3
import sys


def solve(H: int, W: int, D: int, A: "List[List[int]]", Q: int, L: "List[int]", R: "List[int]"):
    K = {}
    for i in range(H):
        for j in range(W):
            K[A[i][j]] = (i, j)
    B = [[0 for _ in range(W)] for _ in range(H)]
    for i in range(D+1, H*W+1):
        j = i % D
        ti, tj = K[i]
        si, sj = K[i-D]
        B[ti][tj] = B[si][sj] + abs(ti-si) + abs(tj-sj)
    for q in range(Q):
        ri, rj = K[R[q]]
        li, lj = K[L[q]]
        s = B[ri][rj] - B[li][lj]
        print(s)
    return


# Generated by 1.1.5 https://github.com/kyuridenamida/atcoder-tools  (tips: You use the default template now. You can remove this line by using your custom template)
def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    H = int(next(tokens))  # type: int
    W = int(next(tokens))  # type: int
    D = int(next(tokens))  # type: int
    A = [[int(next(tokens)) for _ in range(W)] for _ in range(H)]  # type: "List[List[int]]"
    Q = int(next(tokens))  # type: int
    L = [int()] * (Q)  # type: "List[int]"
    R = [int()] * (Q)  # type: "List[int]"
    for i in range(Q):
        L[i] = int(next(tokens))
        R[i] = int(next(tokens))
    solve(H, W, D, A, Q, L, R)

if __name__ == '__main__':
    main()
